def cidr_contains(cidr: str, ip: str) -> bool:
    def parse_ipv4(value: str) -> int:
        if not isinstance(value, str):
            raise ValueError("IPv4 address must be a string")

        parts = value.split(".")
        if len(parts) != 4:
            raise ValueError("IPv4 address must contain four octets")

        octets = []
        for part in parts:
            if not part or any(ch not in "0123456789" for ch in part):
                raise ValueError("Invalid IPv4 octet")
            number = int(part)
            if number < 0 or number > 255:
                raise ValueError("IPv4 octet out of range")
            octets.append(number)

        return (
            (octets[0] << 24)
            | (octets[1] << 16)
            | (octets[2] << 8)
            | octets[3]
        )

    if not isinstance(cidr, str) or cidr.count("/") != 1:
        raise ValueError("CIDR must contain exactly one slash")

    network_text, prefix_text = cidr.split("/")
    if not prefix_text or any(ch not in "0123456789" for ch in prefix_text):
        raise ValueError("Invalid prefix length")

    prefix = int(prefix_text)
    if prefix < 0 or prefix > 32:
        raise ValueError("Prefix length must be between 0 and 32")

    network = parse_ipv4(network_text)
    address = parse_ipv4(ip)

    mask = (0xFFFFFFFF << (32 - prefix)) & 0xFFFFFFFF
    return (network & mask) == (address & mask)
